	const drive = new Drive({ operationId }, baseContext);
	lane.activeDrive = drive;
	const current = lane.state.operation.state;
	return {
		session,
		lane,
		drive,
		events,
		operationId,
		assistantEntryId,
		resultEntryIds,
		run: () => runTools(lane, drive, current),
		async toolResult(index) {
			const entry = await session.getEntry(resultEntryIds[index], baseContext);
