	const f = await fixture({
		calls,
		tools: [],
		persistedReplay: ["safe"],
		extraWrites: ({ operationId, resultEntryIds }) => [
			values.setValue(values.operationToolArgs(operationId, "turn-1", 0), { value: "persisted" }),
			values.setValue(values.pendingToolOutput(operationId, resultEntryIds[0]), {
				content: [{ type: "text", text: "durable partial" }],
				details: { progress: "kept" },
			}),
		],
	});
	let error;
	try {
		await f.run();
	} catch (e) {
		error = e;
	}
	console.log("scenario1 error:", error && String(error));
	const message = await f.toolResult(0);
	console.log("scenario1 message:", JSON.stringify(message, null, 2));
	console.log("scenario1 events:", f.events.map((e) => e.type).join(","));
}
process.exit(0);

